import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph User + Dev Monthly Meetup - May 2025","description":"","frontmatter":{"title":"Ceph User + Dev Monthly Meetup - May 2025","date":"2025-05-21T00:00:00.000Z","updated":"2025-05-22T00:00:00.000Z","tags":["Ceph","分布式存储","开发者会议","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_User_+_Dev_Monthly_Meetup_-_May_2025.md","filePath":"posts/2025/Ceph_User_+_Dev_Monthly_Meetup_-_May_2025.md","lastUpdated":1780459816000}'),l={name:"posts/2025/Ceph_User_+_Dev_Monthly_Meetup_-_May_2025.md"};function d(i,e,n,s,p,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h3><ul><li><strong>会议主题</strong>: Ceph 高级用户讨论会 - 来自 Cephalocon 的反馈总结</li><li><strong>主持人</strong>: Dan Vanderster</li><li><strong>会议时间</strong>: 近期周会</li><li><strong>参与人员</strong>: Dan Vanderster, Laura, Enrico, Casey, Brian 等核心开发成员及社区用户</li></ul><h3 id="关键讨论议题" tabindex="-1">关键讨论议题 <a class="header-anchor" href="#关键讨论议题" aria-label="Permalink to &quot;关键讨论议题&quot;">​</a></h3><ol><li><p><strong>集群再平衡优化 (Balancer/Upmap)</strong>: 讨论了将 <code>upmap remapped</code> 和 <code>PG remapper</code> 逻辑整合到 Balancer 模块，以及处理 degraded PGs 的情况。计划将 upmap 逻辑集成到 balancer 模块，并增加配置选项以允许在 degraded 状态下继续运行 balancer。</p></li><li><p><strong>OSD 重启与维护优化</strong>: 讨论了 OSD 重启时产生的延迟峰值和 PG peering 过程对性能的影响。建议在维护模式下自动设置 <code>no-up</code> 和 <code>primary-affinity=0</code>，分阶段重启 OSD，并在所有 PGs 完成peering后解除 <code>no-out</code> 标志。</p></li><li><p><strong>RGW 性能调优</strong>: 讨论了慢速 OSD 对 RGW 索引操作的影响以及默认线程池配置在高负载场景下的不足。建议增加 <code>rgw_thread_pool_size</code> 和 <code>rgw_max_concurrent_requests</code>，推进 async 化改造，并创建 RGW 性能调优文档。</p></li><li><p><strong>CephFS 灾难恢复</strong>: 讨论了现有灾难恢复文档步骤复杂，自动化程度低的问题。建议添加流程图明确各步骤执行条件和风险，并考虑让 MDS 在启动失败时自动执行部分恢复步骤。</p></li><li><p><strong>MClock 与 WPQ 调度器</strong>: 讨论了 MClock 基准测试结果与实际 HDD 性能存在差异，以及用户对 MClock 稳定性仍存疑虑的问题。建议改进 OSD 基准测试工具准确性，提供标准 <code>fio</code> 测试方法验证设备性能，并计划开展技术讲座展示 MClock 工作原理和调优方法。</p></li></ol><h3 id="决议事项" tabindex="-1">决议事项 <a class="header-anchor" href="#决议事项" aria-label="Permalink to &quot;决议事项&quot;">​</a></h3><ul><li>将 upmap 逻辑整合到 balancer 模块（目标版本：U release）</li><li>优化 sephadm 主机维护流程，自动处理 <code>no-up</code> 和 primary-affinity</li><li>编写 RGW 性能调优最佳实践文档</li><li>改进 CephFS 灾难恢复文档的可操作性</li><li>组织 MClock 技术讲座并改进基准测试工具</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务项</th><th>负责人</th><th>时间节点</th></tr></thead><tbody><tr><td>研究 upmap 集成方案</td><td>NA &amp; Casey</td><td>U release周期</td></tr><tr><td>验证 OSD map 修剪行为</td><td>Brian &amp; Rados团队</td><td>1个月内</td></tr><tr><td>创建 RGW 调优文档</td><td>Anscar</td><td>下月会议前</td></tr><tr><td>改进 CephFS DR 文档</td><td>MDS团队</td><td>Tentacle发布后</td></tr><tr><td>组织 MClock 技术讲座</td><td>NA &amp; Joel</td><td>下季度</td></tr></tbody></table><h3 id="未完成讨论" tabindex="-1">未完成讨论 <a class="header-anchor" href="#未完成讨论" aria-label="Permalink to &quot;未完成讨论&quot;">​</a></h3><ul><li>sephadm 和容器化改进</li><li>PG autoscaler 算法优化</li><li>多站点部署挑战</li></ul><p>下次会议时间: 待定（预计1个月后）</p>',11)])])}const u=t(l,[["render",d]]);export{h as __pageData,u as default};
